const serviceDetails: Record<string, { intro: string; benefits: string[]; process: string; faqs: FAQItem[] }> = {
  "white-fillings": { intro: "White fillings restore teeth damaged by decay using a tooth-coloured resin material that blends seamlessly with your natural smile. Unlike traditional amalgam fillings, composite resin bonds directly to the tooth, providing excellent support while preserving more of your natural tooth structure.", benefits: ["Matches the natural colour of your teeth", "Bonds directly to tooth structure", "Less tooth removal required", "Durable and long-lasting", "Mercury-free option"], process: "After removing the decayed portion and applying local anesthetic, we clean and prepare the area. The composite resin is applied in layers, shaped to match your bite, and hardened with a curing light.", faqs: [{ question: "What are white fillings?", answer: "White fillings are made from a durable resin material that matches the colour of your natural teeth. They are used to repair teeth affected by decay, small fractures, or minor wear." }, { question: "When are white fillings needed?", answer: "You may need a composite filling if you have:", bullets: ["A cavity caused by tooth decay", "A chipped or slightly broken tooth", "Worn enamel", "An old metal filling you would like replaced"] }, { question: "What is the composite filling process?", answer: "The area is gently numbed for comfort. The decayed portion of the tooth is carefully removed. The tooth is cleaned and prepared. The composite material is applied in layers and hardened with a special light. The filling is shaped and polished to match your natural tooth. Most fillings can be completed in a single appointment." }, { question: "What are the benefits of white fillings?", answer: "White fillings offer:", bullets: ["Natural appearance that blends with your smile", "Strong bonding that supports remaining tooth structure", "Less removal of healthy tooth compared to metal fillings", "Reduced sensitivity in many cases"] }, { question: "How should I care for my filling?", answer: "After your appointment, you can typically eat and drink normally once the numbness wears off. Good oral hygiene, including brushing, flossing, and regular dental visits, will help extend the life of your filling. If you experience sensitivity or notice any changes in your bite, let us know so we can make adjustments if needed." }] },
  "dentures": { intro: "Dentures are removable (or implant-supported) dental appliances that replace missing teeth and surrounding gum tissue. Today's dentures are more natural-looking and comfortable than ever, and they can be customized to match your facial features, bite, and smile goals.", benefits: ["Restores the ability to eat and speak comfortably", "Improves facial appearance and self-confidence", "Custom-fitted for maximum comfort", "Full, partial, and implant-supported options", "Immediate dentures available same day as extraction"], process: "The process typically involves several appointments. We take impressions and measurements of your jaws, create a model, and make adjustments until the fit and appearance are just right.", faqs: [{ question: "What are dentures?", answer: "Dentures are removable (or implant-supported) dental appliances that replace missing teeth and surrounding gum tissue. Today's dentures are more natural-looking and comfortable than ever, and they can be customized to match your facial features, bite, and smile goals." }, { question: "What types of dentures are available?", answer: "", bullets: ["Full Dentures — A full set of upper, lower, or both when all teeth are missing, crafted to restore your smile and facial support.", "Partial Dentures — Fill gaps when healthy natural teeth remain and help prevent nearby teeth from shifting.", "Immediate Dentures — Placed the same day teeth are removed so you are never without a smile. A final denture may be made later once gums fully heal.", "Implant-Supported Dentures — Anchored by dental implants for extra stability and improved chewing strength."] }, { question: "What are the signs you may need dentures?", answer: "You may be a good candidate for dentures if you:", bullets: ["Have multiple missing teeth", "Struggle with chewing or speaking clearly", "Feel self-conscious about gaps in your smile", "Have loose or failing teeth due to gum disease", "Wear older dentures that feel uncomfortable or unstable"] }, { question: "What are the benefits of modern dentures?", answer: "Dentures can help you:", bullets: ["Restore your ability to chew comfortably", "Support facial structure (reduce \"sunken\" appearance)", "Protect remaining teeth (for partial dentures)"] }, { question: "What is the denture process at Astra Dental Centre?", answer: "", bullets: ["Consultation & Oral Exam — We assess your gums, jaw, bite, and overall oral health.", "Treatment Planning — We recommend the best option — full, partial, immediate, or implant-supported.", "Custom Measurements & Impressions — Detailed measurements help create dentures that look natural and fit comfortably.", "Try-In & Fine Adjustments — We ensure your denture feels right and looks great before finalizing.", "Aftercare & Ongoing Support — As your mouth changes over time, we offer relines, adjustments, repairs, and guidance."] }, { question: "When do dentures need adjustments, relines, or repairs?", answer: "Even well-made dentures may need updates over time. We can help if your dentures:", bullets: ["Slip or click while talking", "Cause sore spots or irritation", "Are cracked, worn, or broken"] }, { question: "How should you care for your dentures?", answer: "To keep your dentures in great shape:", bullets: ["Clean them daily with a denture brush and cleanser", "Remove them at night (unless directed otherwise)", "Store them in water or denture solution", "Keep your gums and tongue clean", "Visit us for routine exams and adjustments"] }] },
  "inlay-restorations": { intro: "An inlay is a custom-made dental restoration that fits precisely inside the grooves of a tooth. Unlike traditional fillings that are shaped directly in the mouth, inlays are fabricated in a dental lab (or digitally designed) for a precise and durable fit. Porcelain inlays are especially popular because they blend naturally with your surrounding teeth.", benefits: ["Conserves more natural tooth structure", "Stronger and more durable than traditional fillings", "Natural-looking porcelain matches your teeth", "Precise custom fit with excellent contact", "Porcelain resists staining better than composite"], process: "We examine the tooth and remove decay or damaged portions while preserving healthy enamel. Precise impressions are taken to ensure a perfect fit. Your inlay is crafted to match your tooth's shape and shade, then securely bonded in place — restoring its strength and function.", faqs: [{ question: "What is an inlay restoration?", answer: "An inlay is a custom-made dental restoration that fits precisely inside the grooves of a tooth. Unlike traditional fillings shaped directly in the mouth, inlays are fabricated in a dental lab for a precise and durable fit. They are typically made from:", bullets: ["Tooth-colored porcelain", "Composite resin", "Gold (in some cases)"] }, { question: "When is an inlay recommended?", answer: "You may benefit from an inlay if:", bullets: ["You have moderate tooth decay", "An old filling has failed or cracked", "The tooth structure is too strong for a crown but too damaged for a filling", "You want a more durable, long-lasting alternative to large fillings"] }, { question: "What are the benefits of inlay restorations?", answer: "", bullets: ["Conservative Treatment — Inlays preserve more natural tooth structure compared to crowns.", "Durability — They are stronger and more long-lasting than traditional fillings.", "Natural Appearance — Porcelain inlays match the colour of your natural teeth.", "Precise Fit — Custom fabrication ensures excellent contact with surrounding teeth.", "Stain Resistance — Porcelain resists staining better than white fillings."] }, { question: "What is the difference between an inlay, filling, and crown?", answer: "Fillings are ideal for small areas of decay. Inlays are used when the damaged area is larger and needs additional strength. Crowns are recommended when most of the tooth structure is compromised. During your consultation, we will recommend the most conservative and effective option for your specific situation." }, { question: "How long do inlays last?", answer: "With proper care, inlays can last 10–15 years or longer. Maintaining good oral hygiene and attending regular dental checkups will help extend their lifespan." }, { question: "How should you care for your inlay?", answer: "Caring for an inlay is simple:", bullets: ["Brush twice daily", "Floss regularly", "Avoid chewing very hard objects", "Visit us for routine exams and cleanings"] }] },
  "onlay-restorations": { intro: "An onlay is a custom-made restoration that repairs a tooth with moderate to extensive decay, fractures, or old failing fillings. It covers one or more cusps of your tooth and reinforces it so it can handle normal biting and chewing. Think of an onlay as a partial crown that restores the tooth where it needs support without covering the entire tooth in every case.", benefits: ["Conservative — preserves more natural tooth than a full crown", "Natural-looking materials that blend with your tooth", "Improved bite and function with a precise custom fit", "Long-lasting protection for teeth prone to cracking", "Stronger alternative to repeated large fillings"], process: "We examine the tooth, discuss symptoms, and prepare it by removing decay or damaged areas. Your onlay is made to match your tooth's shape, bite, and shade for a seamless result. Once ready, the onlay is permanently bonded, polished, and adjusted so it feels natural when you bite.", faqs: [{ question: "What is an onlay restoration?", answer: "An onlay is a custom-made restoration that repairs a tooth with moderate to extensive decay, fractures, or old failing fillings. It covers one or more cusps of your tooth and reinforces it so it can handle normal biting and chewing — like a partial crown that restores where support is needed without covering the entire tooth." }, { question: "When is an onlay recommended?", answer: "Onlay restorations are commonly recommended when:", bullets: ["A cavity or fracture is too large for a regular filling", "An old filling has broken down or cracked", "A tooth has weakened cusps that need reinforcement", "You want a long-lasting alternative to repeated large fillings", "A crown may be more coverage than necessary"] }, { question: "What are the benefits of onlay restorations?", answer: "Onlays are a popular restorative choice because they offer:", bullets: ["Conservative — preserves more natural tooth than many full crowns", "Natural-looking materials that blend with your tooth", "Improved bite and function with a precise custom fit", "Long-lasting protection for teeth that are prone to cracking"] }, { question: "What is the difference between an onlay, filling, and crown?", answer: "Fillings are best for small-to-medium cavities. Onlays are ideal for larger damage where part of the tooth needs reinforcement. Crowns cover the entire tooth and are used when damage is extensive. At Astra Dental Centre, we will recommend the most conservative option that still protects your tooth properly for the long term." }, { question: "What materials are used for onlays?", answer: "Onlays may be made from durable, natural-looking materials such as porcelain/ceramic or composite-based restorations, depending on your tooth, bite, and aesthetic goals. We will recommend the best option based on function and longevity." }, { question: "How should you care for your onlay?", answer: "Onlays are cared for like natural teeth:", bullets: ["Avoid chewing ice or very hard objects", "Visit us regularly for exams and cleanings", "Let us know if you feel any high spots or bite changes"] }] },
  "bite-guards": { intro: "A bite guard (also called a night guard) is a custom dental appliance worn over your teeth — usually at night — to prevent damage caused by grinding (bruxism) or clenching. Unlike over-the-counter options, a professionally made bite guard is custom-fitted for your smile, offering better comfort, durability, and protection.", benefits: ["Protects teeth from wear, fractures, and enamel damage", "Reduces jaw tension and muscle strain", "Helps prevent TMJ discomfort", "Improves sleep comfort", "Long-lasting and durable compared to store-bought guards"], process: "We begin with an examination of your teeth, jaw, and symptoms. Detailed impressions or digital scans are taken to create a perfectly fitted appliance. Your guard is crafted from durable, high-quality material, then fitted and adjusted for proper comfort.", faqs: [{ question: "What is a bite guard?", answer: "A bite guard (also called a night guard) is a custom dental appliance worn over your teeth — usually at night — to prevent damage caused by grinding (bruxism) or clenching. Unlike over-the-counter options, a professionally made bite guard is custom-fitted for your smile, offering better comfort, durability, and protection." }, { question: "What are the signs you may need a bite guard?", answer: "You may benefit from a bite guard if you experience:", bullets: ["Jaw pain or tightness, especially in the morning", "Frequent headaches or facial soreness", "Worn, chipped, or cracked teeth", "Tooth sensitivity without clear cause", "Clicking or discomfort in the jaw (TMJ symptoms)", "A partner noticing grinding sounds during sleep"] }, { question: "What are the benefits of a custom bite guard?", answer: "Choosing a custom bite guard from our Langley dental office offers several advantages:", bullets: ["Protects teeth from wear, fractures, and enamel damage", "Reduces jaw tension and muscle strain", "Helps prevent TMJ discomfort", "Improves sleep comfort", "Long-lasting and durable compared to store-bought guards"] }, { question: "What is the difference between custom and store-bought bite guards?", answer: "While pharmacy guards are available, they often:", bullets: ["Fit loosely or feel bulky", "Wear down quickly", "Offer limited protection", "Can worsen jaw alignment issues"] }, { question: "What is the bite guard process at Astra Dental Centre?", answer: "Getting a bite guard is simple and comfortable:", bullets: ["Examination — We evaluate your teeth, jaw, and symptoms.", "Impressions or Digital Scans — We take detailed measurements to create a perfectly fitted appliance.", "Custom Fabrication — Your guard is crafted from durable, high-quality material.", "Fitting & Adjustments — We ensure proper fit and comfort, making adjustments if needed."] }, { question: "How should you care for your bite guard?", answer: "To keep your guard in good condition:", bullets: ["Rinse after each use", "Brush gently with a soft toothbrush (no toothpaste)", "Store in its ventilated case", "Bring it to your regular dental check-ups"] }] },
  "bridges": { intro: "A dental bridge is a fixed restoration used to replace one or more missing teeth. It consists of artificial teeth (pontics) that fill the gap, supported by crowns placed on neighbouring teeth. The bridge is securely bonded in place, restoring both appearance and function.", benefits: ["Restores your smile and facial balance", "Improves chewing and speaking ability", "Prevents shifting of nearby teeth", "Maintains proper bite alignment", "Custom-made for a natural look"], process: "The supporting teeth are gently shaped to accommodate crowns. Precise impressions are taken for a perfect fit. A temporary bridge protects your teeth while your custom bridge is created. At the final visit, your permanent bridge is bonded and adjusted for comfort and bite alignment.", faqs: [{ question: "What is a dental bridge?", answer: "A dental bridge is a fixed restoration used to replace one or more missing teeth. It consists of:", bullets: ["Artificial tooth/teeth (pontics) that fill the gap", "Supporting crowns placed on neighbouring teeth (abutment teeth)"] }, { question: "When is a dental bridge recommended?", answer: "You may be a good candidate for a dental bridge if you:", bullets: ["Have one or more missing teeth", "Have healthy neighbouring teeth to support the bridge", "Want a fixed (non-removable) tooth replacement option", "Wish to prevent teeth from shifting into empty spaces"] }, { question: "What are the benefits of dental bridges?", answer: "Dental bridges offer many advantages:", bullets: ["Restores your smile and facial balance", "Improves chewing and speaking ability", "Prevents shifting of nearby teeth", "Maintains proper bite alignment", "Custom-made for a natural look"] }, { question: "What types of dental bridges are available?", answer: "Depending on your needs, we may recommend:", bullets: ["Traditional Bridge — The most common type, supported by crowns placed on teeth on either side of the gap.", "Cantilever Bridge — Used when there is support from only one adjacent tooth.", "Implant-Supported Bridge — Anchored by dental implants rather than natural teeth, offering added stability."] }, { question: "What is the dental bridge process?", answer: "Getting a dental bridge typically involves:", bullets: ["Examination & Treatment Planning — We assess your oral health and discuss your goals.", "Tooth Preparation — The supporting teeth are gently shaped to accommodate crowns.", "Impressions or Digital Scans — We take detailed measurements to ensure a precise fit.", "Temporary Bridge — A temporary restoration protects your teeth while your custom bridge is being created.", "Final Placement — Your permanent bridge is bonded into place and adjusted for comfort and bite alignment."] }, { question: "How should you care for your dental bridge?", answer: "Proper care helps your bridge last many years:", bullets: ["Brush twice daily", "Floss carefully around and under the bridge", "Use recommended cleaning tools (such as floss threaders)", "Attend regular dental exams and cleanings"] }] },
  "crowns": { intro: "A dental crown is a custom-fitted cap that covers the entire visible portion of a tooth. It restores strength and appearance and is commonly used to protect teeth that cannot be restored with fillings alone.", benefits: ["Restores full tooth function for chewing and speaking", "Strengthens weakened teeth", "Protects against further damage", "Improves the appearance of discoloured or misshapen teeth", "Long-lasting and durable solution"], process: "We remove decay or damaged areas and shape the tooth to support the crown. Precise impressions or digital scans are taken to create your custom crown. A temporary crown protects your tooth while the permanent one is fabricated. At the final visit, your crown is bonded securely and adjusted for comfort.", faqs: [{ question: "What is a dental crown?", answer: "A dental crown is a custom-fitted \"cap\" that covers the entire visible portion of a tooth. It restores:", bullets: ["Strength", "Appearance"] }, { question: "When is a dental crown recommended?", answer: "You may need a dental crown if you have:", bullets: ["A cracked or fractured tooth", "A large cavity that cannot support a filling", "A tooth weakened after a root canal", "A severely worn-down tooth", "A broken or failing large filling", "A dental implant that requires restoration"] }, { question: "What are the benefits of dental crowns?", answer: "Dental crowns provide several important advantages:", bullets: ["Restores full function for chewing and speaking", "Strengthens weakened teeth", "Protects against further damage", "Improves the appearance of discoloured or misshapen teeth", "Long-lasting and durable solution"] }, { question: "What types of dental crowns are available?", answer: "We offer different crown materials depending on your needs:", bullets: ["Porcelain or Ceramic Crowns — Highly aesthetic and ideal for visible front teeth.", "Porcelain-Fused-to-Metal Crowns — Strong and durable with a natural outer layer.", "Zirconia Crowns — Extremely strong and aesthetically pleasing, often used for back teeth."] }, { question: "What is the dental crown process?", answer: "Getting a dental crown typically involves two visits:", bullets: ["Examination & Preparation — We remove decay or damaged areas and shape the tooth to support the crown.", "Impressions or Digital Scans — Precise measurements are taken to create your custom crown.", "Temporary Crown — A temporary crown is placed to protect your tooth while your permanent crown is fabricated.", "Final Placement — Your custom crown is bonded securely in place and adjusted for comfort and proper bite alignment."] }, { question: "How should you care for your dental crown?", answer: "Dental crowns are maintained just like natural teeth:", bullets: ["Brush twice daily", "Floss regularly", "Avoid chewing extremely hard objects", "Visit us for routine exams and cleanings"] }] },
  "zoom-teeth-whitening": { intro: "Zoom is a professional in-office whitening treatment that uses a specially formulated whitening gel activated by a blue LED light. This combination helps break down stains and lighten the colour of your teeth quickly and safely.", benefits: ["Faster results than over-the-counter kits", "Stronger, professionally applied whitening agents", "Supervised treatment for safety and comfort", "More even and predictable whitening", "Many patients achieve results several shades whiter in about an hour"], process: "Your lips and gums are carefully protected before applying the whitening gel. The whitening gel is activated using a specialized LED light in multiple short sessions. After treatment, you will see immediate brightening results.", faqs: [{ question: "What is Zoom teeth whitening?", answer: "Zoom is a professional in-office whitening treatment that uses a specially formulated whitening gel activated by a blue LED light. Compared to over-the-counter whitening kits, Zoom offers:", bullets: ["Faster results", "Stronger, professionally applied whitening agents", "Supervised treatment for safety and comfort", "More even and predictable whitening"] }, { question: "Why choose professional whitening?", answer: "With professional Zoom whitening at Astra Dental Centre, you receive:", bullets: ["A customized approach based on your tooth shade", "Protection for your gums and soft tissues", "Controlled application for maximum safety", "Immediate, noticeable improvement"] }, { question: "What should you expect during your Zoom appointment?", answer: "Your Zoom whitening appointment is simple and comfortable:", bullets: ["Smile Assessment — We examine your teeth and discuss your whitening goals.", "Preparation — Your lips and gums are carefully protected before applying the whitening gel.", "Zoom Activation — The whitening gel is activated using a specialized LED light in multiple short sessions.", "Final Results — After treatment, you'll see immediate brightening results."] }, { question: "Is Zoom whitening right for you?", answer: "Zoom whitening is ideal if you:", bullets: ["Have yellow or stained teeth", "Want fast, visible results", "Have a special event coming up", "Prefer professional supervision for comfort and safety"] }, { question: "How long do results last?", answer: "Results can last several months to a few years depending on:", bullets: ["Oral hygiene habits", "Diet (coffee, wine, tea, etc.)", "Smoking", "Regular dental cleanings"] }] },
  "porcelain-veneers": { intro: "Porcelain veneers are thin, custom-made shells that are bonded to the front surface of your teeth. They are carefully designed to match your natural smile while correcting cosmetic imperfections, providing a smooth, bright, and symmetrical appearance.", benefits: ["Create a brighter, more even smile", "Look natural and reflect light like real enamel", "Resist staining better than natural teeth", "Require minimal removal of tooth structure", "Offer long-lasting results with proper care"], process: "We discuss your goals and evaluate whether veneers are right for you. A small amount of enamel is gently removed to create space for the veneer. Precise impressions are taken, and your veneers are crafted from high-quality porcelain to match your desired shade and shape. They are then securely bonded and adjusted for comfort.", faqs: [{ question: "What are porcelain veneers?", answer: "Porcelain veneers are thin, custom-made shells that are bonded to the front surface of your teeth. Veneers can improve:", bullets: ["Discoloured or stained teeth", "Chipped or cracked teeth", "Small gaps between teeth", "Slightly misaligned or uneven teeth", "Worn or misshapen teeth"] }, { question: "What are the benefits of porcelain veneers?", answer: "Porcelain veneers are a popular cosmetic treatment because they:", bullets: ["Create a brighter, more even smile", "Look natural and reflect light like real enamel", "Resist staining better than natural teeth", "Require minimal removal of tooth structure", "Offer long-lasting results with proper care"] }, { question: "What is the porcelain veneer process?", answer: "Your veneer treatment typically involves:", bullets: ["Consultation & Smile Planning — We discuss your goals and evaluate whether veneers are right for you.", "Tooth Preparation — A small amount of enamel is gently removed to create space for the veneer.", "Impressions or Digital Scans — Precise measurements are taken to ensure a perfect fit.", "Custom Veneer Fabrication — Your veneers are crafted from high-quality porcelain to match your desired shade and shape.", "Bonding & Final Adjustments — The veneers are securely bonded to your teeth and adjusted for comfort and appearance."] }, { question: "Are porcelain veneers right for you?", answer: "Veneers are ideal for patients who:", bullets: ["Have healthy teeth and gums", "Want a cosmetic improvement rather than orthodontic correction", "Are looking for a long-term smile enhancement", "Maintain good oral hygiene habits"] }] },
  "cerec-dentistry": { intro: "CEREC is a modern dental system that uses digital 3D scanning, computer-aided design (CAD), and in-office milling technology. This allows us to create custom ceramic restorations right here in our Langley office — often in a single appointment.", benefits: ["Same-day treatment — no second appointment", "No messy impressions", "No temporary crowns", "Natural-looking ceramic restorations", "Strong, durable materials with a precise digital fit"], process: "Instead of traditional impressions, we take a precise 3D digital scan of your tooth. Using advanced software, we design your custom restoration to match your bite and natural tooth shape. Your restoration is then milled from a solid block of high-quality ceramic right in our office, bonded securely, and polished for a natural finish.", faqs: [{ question: "What is CEREC dentistry?", answer: "CEREC is a modern dental system that uses:", bullets: ["Digital 3D scanning", "Computer-aided design (CAD)", "In-office milling technology"] }, { question: "What are the benefits of CEREC dentistry?", answer: "CEREC offers several advantages over traditional restorative methods:", bullets: ["Same-day treatment — no second appointment", "No messy impressions", "No temporary crowns", "Natural-looking ceramic restorations", "Strong, durable materials", "Precise digital fit"] }, { question: "What can CEREC be used for?", answer: "CEREC technology is commonly used for:", bullets: ["Dental crowns", "Inlays", "Onlays", "Veneers", "Replacing old metal fillings"] }, { question: "What is the CEREC process at Astra Dental Centre?", answer: "", bullets: ["Digital Scan — Instead of traditional impressions, we take a precise 3D digital scan of your tooth.", "Computer Design — Using advanced software, we design your custom restoration to match your bite and natural tooth shape.", "On-Site Milling — Your restoration is milled from a solid block of high-quality ceramic right in our office.", "Placement — Once ready, the restoration is bonded securely to your tooth and polished for a natural finish."] }, { question: "Why choose CEREC dentistry in Langley?", answer: "Traditional crowns usually require:", bullets: ["Two appointments", "Temporary restorations", "A waiting period of one to two weeks"] }, { question: "Is CEREC right for you?", answer: "CEREC is ideal for patients who:", bullets: ["Have busy schedules", "Need a crown or restoration", "Want a metal-free, natural-looking option", "Prefer fewer dental visits"] }] },
  "dental-exams-and-cleanings": { intro: "Regular dental exams and professional cleanings are the most important preventive tools for maintaining your oral health. We recommend visits every six months for most patients.", benefits: ["Early detection of cavities and gum disease", "Removal of plaque and tartar buildup", "Oral cancer screening", "Personalized oral hygiene advice", "Polishing for a fresh, clean feel"], process: "Your hygienist will remove plaque and tartar, then polish your teeth. The dentist will conduct a thorough examination of your teeth, gums, and soft tissues, including an oral cancer screening.", faqs: [{ question: "Why are dental exams important?", answer: "Even if your teeth feel fine, dental problems often develop without noticeable symptoms. Regular dental exams help us:", bullets: ["Detect cavities early", "Monitor existing restorations", "Screen for oral cancer", "Check for bite or jaw issues", "Evaluate overall oral health"] }, { question: "What happens during a dental exam?", answer: "During your visit, your dentist may:", bullets: ["Comprehensive Examination — We carefully examine your teeth, gums, and mouth for signs of decay, infection, or other concerns.", "Digital X-Rays — If needed, digital radiographs help detect cavities between teeth, bone loss, or hidden issues beneath the surface.", "Gum Health Evaluation — We assess your gums for inflammation, recession, or signs of periodontal (gum) disease.", "Oral Cancer Screening — We examine your lips, tongue, throat, and surrounding tissues for any abnormal changes."] }, { question: "What is included in a professional dental cleaning?", answer: "Even with excellent brushing and flossing habits, plaque and tartar can build up over time. A professional cleaning helps:", bullets: ["Remove hardened tartar (calculus)", "Reduce gum inflammation", "Prevent cavities", "Freshen your breath", "Maintain healthy gums"] }, { question: "How often should you have a dental check-up?", answer: "Most patients benefit from exams and cleanings every six months. However, some individuals with gum disease or specific oral health concerns may require more frequent visits. We personalize your preventive schedule based on your unique needs." }, { question: "Who can benefit from dental exams and cleanings?", answer: "At Astra Dental Centre, we provide dental exams and cleanings for:", bullets: ["Children", "Teens", "Adults", "Seniors"] }, { question: "What are the benefits of routine dental visits?", answer: "Regular exams and cleanings help:", bullets: ["Prevent tooth decay and gum disease", "Save money by avoiding major treatments", "Maintain a bright, healthy smile", "Support overall health"] }] },
  "dental-x-rays": { intro: "Dental X-rays are an essential diagnostic tool that allows us to see areas of your mouth not visible to the naked eye, including bone levels, roots, and developing teeth.", benefits: ["Detects hidden cavities", "Monitors bone health", "Identifies abscesses and infections", "Low radiation digital technology", "Aids in treatment planning"], process: "Digital X-rays are quick and comfortable. A sensor is placed in your mouth and the results appear on a chairside monitor instantly, allowing us to review findings with you right away.", faqs: [{ question: "Why are dental X-rays important?", answer: "Many dental concerns develop beneath the surface of the teeth or below the gum line. Without X-rays, these problems may go unnoticed. Dental X-rays help us detect:", bullets: ["Cavities between teeth", "Bone loss related to gum disease", "Abscesses or infections", "Impacted teeth", "Cysts or tumours", "Cracks in teeth", "Problems with developing teeth", "Issues beneath existing fillings or crowns"] }, { question: "What are the benefits of digital X-ray technology?", answer: "At Astra Dental Centre, we use digital radiography, which offers several advantages:", bullets: ["Significantly lower radiation exposure", "Instant image viewing", "Enhanced image clarity", "Environmentally friendly (no chemical processing)", "Easy sharing with specialists if needed"] }, { question: "How often are dental X-rays needed?", answer: "The frequency of X-rays depends on:", bullets: ["Your age", "Your oral health history", "Risk of cavities or gum disease", "Symptoms you may be experiencing"] }, { question: "Are dental X-rays safe?", answer: "Yes. Modern dental X-rays use very low levels of radiation. We also take additional precautions such as:", bullets: ["Lead aprons", "Thyroid collars", "Advanced digital sensors"] }, { question: "What should you expect during a dental X-ray?", answer: "Dental X-rays are quick and comfortable:", bullets: ["A small digital sensor is gently positioned in your mouth", "The image is captured in seconds", "The image appears instantly on our screen for review"] }, { question: "Who can benefit from dental X-rays?", answer: "X-rays are important for monitoring both children and adults. In children, they help track:", bullets: ["Tooth development", "Eruption patterns", "Alignment issues"] }] },
  "tmj": { intro: "Temporomandibular joint (TMJ) disorders affect the joint connecting your jaw to your skull, causing pain, clicking, and difficulty chewing. We offer comprehensive evaluation and treatment.", benefits: ["Relief from jaw pain and headaches", "Improved jaw function", "Non-invasive treatment options", "Custom night guard therapy", "Long-term symptom management"], process: "We begin with a thorough evaluation of your jaw, bite, and symptoms. Treatment may include custom oral appliances, bite adjustments, or referral to a specialist depending on the severity.", faqs: [{ question: "What is TMJ?", answer: "TMJ stands for the temporomandibular joint, which connects your lower jaw to your skull. This joint allows you to:", bullets: ["Open and close your mouth", "Chew and speak", "Move your jaw side to side"] }, { question: "What are the common symptoms of TMJ disorder?", answer: "TMJ symptoms can vary from mild to severe and may include:", bullets: ["Jaw pain or tenderness", "Headaches (often in the morning)", "Earaches or ringing in the ears (tinnitus)", "Clicking, popping, or grinding sounds in the jaw", "Difficulty opening or closing the mouth", "Facial pain", "Neck and shoulder discomfort", "Pain while chewing"] }, { question: "What causes TMJ problems?", answer: "TMJ disorders may be caused by:", bullets: ["Teeth grinding or clenching (bruxism)", "Bite misalignment", "Jaw injury", "Arthritis", "Stress-related muscle tension"] }, { question: "What treatment options are available for TMJ?", answer: "We offer conservative, non-surgical TMJ treatment options designed to relieve pain and improve jaw function:", bullets: ["Custom Night Guards — A custom bite guard can reduce grinding and relieve pressure on the jaw joint.", "Bite Adjustment — Correcting uneven bite pressure can help reduce strain on the TMJ.", "Restorative Treatment — In some cases, crowns or orthodontic treatment may help improve jaw alignment.", "Lifestyle Recommendations — We may suggest exercises, stress management, or dietary adjustments to reduce symptoms."] }, { question: "When should you see a dentist for TMJ?", answer: "You should seek evaluation if:", bullets: ["Jaw pain persists", "You have limited mouth opening", "You experience frequent headaches", "Your jaw locks or feels unstable", "Chewing becomes painful"] }] },
  "invisalign": { intro: "Invisalign uses a series of custom-made, clear removable aligners to gradually straighten your teeth without metal brackets or wires — an ideal option for adults and teens wanting discreet orthodontic treatment.", benefits: ["Nearly invisible treatment", "Removable for eating and hygiene", "Comfortable smooth plastic aligners", "Fewer office visits than braces", "Predictable digital treatment planning"], process: "We use a digital scanner to create a 3D model of your teeth and design a personalized treatment plan. Custom aligners are worn 20–22 hours per day, changing every 1–2 weeks.", faqs: [{ question: "What is Invisalign?", answer: "Invisalign is an orthodontic treatment that uses a series of custom-made, transparent aligners to straighten teeth. These aligners are:", bullets: ["Virtually invisible", "Removable", "Comfortable", "Custom-designed for your smile"] }, { question: "What can Invisalign correct?", answer: "Invisalign can effectively treat:", bullets: ["Crooked teeth", "Crowded teeth", "Gaps between teeth", "Overbite", "Underbite", "Crossbite", "Mild to moderate bite alignment issues"] }, { question: "What are the benefits of Invisalign?", answer: "Patients in Langley choose Invisalign because it offers:", bullets: ["Discreet appearance", "No metal brackets or wires", "Removable for eating and brushing", "Comfortable smooth plastic aligners", "Fewer in-office visits", "Predictable digital treatment planning"] }, { question: "What is the Invisalign process at Astra Dental Centre?", answer: "", bullets: ["Consultation & Assessment — We evaluate your teeth, bite, and overall oral health to confirm candidacy.", "Digital Scanning — Using advanced digital imaging, we create a precise 3D model of your teeth.", "Custom Treatment Plan — Your aligners are designed to gradually move your teeth into alignment.", "Wearing Your Aligners — You will wear your aligners for 20–22 hours per day, removing them only to eat, drink, brush, and floss.", "Progress Monitoring — We schedule periodic check-ups to ensure your treatment is progressing as planned."] }, { question: "How long does Invisalign take?", answer: "Treatment time varies depending on the complexity of your case. Many patients complete Invisalign treatment within 6 to 18 months. We will provide a personalized estimate during your consultation." }, { question: "Is Invisalign right for you?", answer: "Invisalign is ideal for teens and adults who want a more subtle orthodontic option. It works best for mild to moderate alignment issues and for patients who are committed to wearing their aligners as directed. Our team will help you decide if Invisalign is the best solution for achieving your smile goals." }] },
  "braces-for-kids": { intro: "Early orthodontic treatment for children can guide jaw development and correct emerging alignment issues at the optimal stage of growth, potentially reducing the complexity of future treatment.", benefits: ["Guides proper jaw development", "Creates space for permanent teeth", "Reduces future treatment complexity", "Boosts self-confidence early", "Modern, comfortable bracket options"], process: "An initial assessment evaluates jaw development, tooth positioning, and bite. A phased treatment plan may include space maintainers or expanders in Phase 1, with full braces applied when most permanent teeth have erupted.", faqs: [{ question: "When should kids see an orthodontic dentist?", answer: "The Canadian Association of Orthodontists recommends that children have their first orthodontic evaluation by age 7. At this stage, we can assess:", bullets: ["Jaw growth", "Bite alignment", "Spacing issues", "Crowding", "Early tooth loss"] }, { question: "Why might a child need braces?", answer: "Braces may be recommended if your child has:", bullets: ["Crooked or crowded teeth", "Gaps between teeth", "Overbite or underbite", "Crossbite", "Jaw alignment issues", "Difficulty chewing or speaking"] }, { question: "What types of braces are available for kids?", answer: "At Astra Dental Centre, we offer orthodontic solutions tailored to your child's needs:", bullets: ["Traditional Metal Braces — Modern metal braces are smaller, more comfortable, and highly effective for correcting a wide range of alignment issues.", "Clear Brackets (in Some Cases) — For children concerned about appearance, more discreet options may be available depending on the case."] }, { question: "What are the benefits of early orthodontic treatment?", answer: "Starting treatment at the right time can:", bullets: ["Guide proper jaw development", "Reduce the need for future tooth extractions", "Improve speech and chewing", "Make oral hygiene easier", "Boost your child's confidence"] }, { question: "What should you expect during braces treatment?", answer: "", bullets: ["Consultation & Assessment — We examine your child's teeth and take digital images or X-rays.", "Personalized Treatment Plan — We design a plan tailored to your child's growth and alignment needs.", "Braces Placement — Braces are gently applied in a comfortable appointment.", "Regular Adjustments — Periodic visits allow us to guide tooth movement safely and effectively."] }, { question: "How should braces be cared for?", answer: "Proper care during treatment is essential. We recommend:", bullets: ["Brushing after every meal", "Using floss threaders or orthodontic floss", "Attending regular check-ups"] }] },
  "braces-for-adults": { intro: "It's never too late to achieve a straight, healthy smile. More adults than ever are choosing orthodontic treatment, with discreet options that fit a professional lifestyle.", benefits: ["Discreet ceramic and clear options", "Improves bite and oral health", "Boosts professional confidence", "Prevents uneven tooth wear", "Proven, effective results"], process: "We perform a comprehensive orthodontic assessment and develop a customized treatment plan. Options include ceramic braces, lingual braces, or Invisalign, depending on your case complexity.", faqs: [{ question: "Why do adults choose braces?", answer: "Many adults seek orthodontic treatment to correct:", bullets: ["Crooked or crowded teeth", "Gaps between teeth", "Bite problems (overbite, underbite, crossbite)", "Shifting teeth after previous orthodontic treatment", "Jaw discomfort related to misalignment"] }, { question: "What are the benefits of braces for adults?", answer: "Orthodontic treatment offers more than just cosmetic improvement:", bullets: ["Improved bite alignment", "Reduced jaw strain", "Easier oral hygiene", "Lower risk of gum disease", "Enhanced confidence", "Long-term dental stability"] }, { question: "What types of braces are available for adults?", answer: "At Astra Dental Centre, we offer modern orthodontic solutions tailored to adult patients:", bullets: ["Traditional Metal Braces — Today's metal braces are smaller and more comfortable than ever. They are highly effective for treating complex alignment issues.", "Clear Braces — Ceramic brackets blend more naturally with your teeth, making them a more discreet option.", "Invisalign Clear Aligners — For eligible cases, Invisalign offers a nearly invisible alternative to traditional braces."] }, { question: "What should you expect during treatment?", answer: "", bullets: ["Comprehensive Consultation — We evaluate your teeth, jaw alignment, and overall oral health.", "Digital Imaging & Planning — Advanced imaging helps us design a personalized treatment plan.", "Braces Placement or Aligner Fitting — Your treatment begins with careful placement and clear instructions.", "Regular Monitoring Visits — We track your progress and make necessary adjustments."] }, { question: "Is it too late for braces?", answer: "Absolutely not. As long as your gums and bone structure are healthy, orthodontic treatment is possible at almost any age. Many adult patients report that choosing braces later in life was one of their best decisions." }] },
  "cracked-teeth-treatment": { intro: "Cracked teeth can cause significant pain and, if left untreated, can lead to infection and tooth loss. We offer advanced diagnostic and treatment options to preserve cracked teeth and eliminate discomfort.", benefits: ["Pain relief", "Prevents further damage", "Saves the natural tooth", "Range of treatment options", "Accurate diagnosis with advanced imaging"], process: "Diagnosis involves a clinical exam and X-rays. Treatment depends on the severity of the crack and may include bonding, a crown, root canal therapy, or in severe cases, extraction and replacement.", faqs: [{ question: "What are the signs of a cracked tooth?", answer: "Cracked teeth do not always show visible damage, but common symptoms include:", bullets: ["Sharp pain when biting or chewing", "Sensitivity to hot or cold", "Pain when releasing biting pressure", "Swelling around the affected tooth", "Intermittent discomfort that comes and goes"] }, { question: "What causes a cracked tooth?", answer: "Teeth can crack due to:", bullets: ["Biting hard foods (ice, nuts, hard candy)", "Teeth grinding or clenching (bruxism)", "Large fillings weakening the tooth structure", "Trauma or injury", "Sudden temperature changes in the mouth", "Natural wear over time"] }, { question: "What types of tooth cracks are there?", answer: "There are different types of cracks, including:", bullets: ["Craze lines (small surface cracks)", "Cracked tooth extending into the pulp", "Split tooth", "Vertical root fractures"] }, { question: "What are the treatment options for cracked teeth?", answer: "At Astra Dental Centre, we tailor treatment based on the severity of the damage:", bullets: ["Dental Bonding — Minor cracks may be repaired with tooth-coloured composite material.", "Dental Crown — A crown protects and strengthens a cracked tooth, preventing further damage.", "Root Canal Therapy — If the crack has reached the pulp (inner nerve), root canal treatment may be necessary to remove infection and preserve the tooth.", "Tooth Extraction — In severe cases where the tooth cannot be saved, extraction may be required."] }, { question: "Why is prompt treatment important?", answer: "Delaying treatment can allow bacteria to enter the crack, leading to infection, abscess formation, and possible bone loss. The sooner a cracked tooth is treated, the better the chance of saving it." }, { question: "How can cracked teeth be prevented?", answer: "You can reduce your risk by:", bullets: ["Avoiding chewing hard objects", "Wearing a custom night guard if you grind your teeth", "Attending regular dental check-ups", "Addressing preventive care helps maintain strong and healthy teeth"] }] },
  "root-amputation": { intro: "Root amputation is a surgical procedure that removes one root from a multi-rooted tooth, allowing the tooth to be preserved when one root is compromised by disease or damage.", benefits: ["Preserves the natural tooth", "Eliminates diseased root", "Maintains chewing function", "Alternative to full extraction"], process: "The procedure is performed under local anesthesia. The compromised root is surgically removed while the remaining tooth and root are preserved. A crown is typically placed afterward.", faqs: [{ question: "What is root amputation?", answer: "Root amputation is a surgical procedure that involves removing one root from a tooth that has multiple roots — typically a molar. This treatment is recommended when:", bullets: ["One root is severely infected", "There is advanced bone loss around a specific root", "A fracture affects only one root", "Previous root canal treatment has failed in one root"] }, { question: "Why save the tooth instead of extracting it?", answer: "Keeping your natural tooth offers many benefits:", bullets: ["Maintains natural chewing function", "Preserves jawbone structure", "Prevents shifting of neighbouring teeth", "Avoids the need for extraction and replacement"] }, { question: "What is the root amputation procedure?", answer: "", bullets: ["Examination & Imaging — We use digital X-rays to assess the extent of infection or damage.", "Root Canal Therapy (If Required) — The tooth may need root canal treatment before or during the procedure.", "Surgical Removal of the Affected Root — The damaged root is carefully removed while preserving the healthy roots.", "Restoration — The remaining tooth structure is reinforced with a crown to restore strength and function."] }, { question: "Is root amputation right for you?", answer: "Root amputation is typically considered when:", bullets: ["Only one root is compromised", "The remaining roots are healthy", "You want to avoid full tooth extraction"] }, { question: "What should you expect after root amputation?", answer: "After the procedure:", bullets: ["Mild discomfort or swelling may occur", "We provide aftercare instructions to promote healing", "A follow-up visit ensures proper recovery"] }] },
  "root-canal-treatment": { intro: "Root canal treatment removes infected or inflamed pulp from inside the tooth, relieving pain and saving the natural tooth from extraction.", benefits: ["Eliminates toothache and infection", "Saves the natural tooth", "Prevents spread of infection", "Restores normal biting function", "Modern techniques make it comfortable"], process: "After numbing the area, we make a small opening in the tooth to access the pulp chamber. The infected tissue is removed, the canals are cleaned and shaped, then filled with a biocompatible material.", faqs: [{ question: "What is a root canal?", answer: "Inside every tooth is soft tissue called the dental pulp. The pulp contains nerves and blood vessels that help the tooth develop. When the pulp becomes infected due to decay, cracks, trauma, or deep cavities, it can cause significant pain and swelling. Root canal treatment removes the infected pulp, cleans and disinfects the inside of the tooth, and seals it to prevent further infection." }, { question: "What are the signs you may need a root canal?", answer: "Common symptoms include:", bullets: ["Persistent tooth pain", "Sensitivity to hot or cold that lingers", "Pain when chewing or biting", "Swollen or tender gums", "Darkening of the tooth", "A small bump on the gums (abscess)"] }, { question: "What is the root canal procedure?", answer: "At Astra Dental Centre, root canal treatment typically involves:", bullets: ["Examination & Digital X-Rays — We assess the extent of infection and confirm the diagnosis.", "Removal of Infected Pulp — The infected tissue is carefully removed from inside the tooth.", "Cleaning & Disinfection — The root canals are cleaned and shaped to eliminate bacteria.", "Sealing the Tooth — The canals are filled and sealed to prevent reinfection.", "Final Restoration — In most cases, a dental crown is placed to strengthen and protect the treated tooth."] }, { question: "Is root canal treatment painful?", answer: "Many patients are surprised to learn that modern root canal therapy is no more uncomfortable than receiving a filling. We use local anesthesia and gentle techniques to ensure your comfort throughout the procedure. The treatment actually relieves pain caused by infection." }, { question: "What are the benefits of saving your natural tooth?", answer: "Root canal treatment allows you to:", bullets: ["Preserve your natural tooth", "Maintain normal chewing ability", "Prevent shifting of neighbouring teeth", "Avoid more costly tooth replacement options", "Protect jawbone health"] }, { question: "What should you expect after a root canal?", answer: "After treatment, mild tenderness may occur for a few days. This can usually be managed with over-the-counter pain relief. Good oral hygiene and regular check-ups help ensure long-term success. With proper care, a root canal-treated tooth can last many years." }] },
  "endodontic-surgery": { intro: "Endodontic surgery (apicoectomy) is recommended when non-surgical root canal treatment is not sufficient to resolve persistent infection or when root anatomy prevents standard treatment.", benefits: ["Saves teeth that could not otherwise be treated", "Resolves persistent infection", "Removes damaged root tip", "Seals the root end", "High success rate"], process: "Under local anesthesia, a small incision is made near the affected tooth. The tip of the root and surrounding infected tissue are removed, and a small filling seals the root end. The site is sutured and monitored.", faqs: [{ question: "What is endodontic surgery?", answer: "Endodontic surgery is a specialized procedure performed when infection or inflammation persists after root canal therapy or when certain conditions cannot be treated from inside the tooth. The most common type of endodontic surgery is an apicoectomy, which involves:", bullets: ["Removing the tip of the tooth root", "Cleaning infected tissue around the root", "Sealing the root end to prevent reinfection"] }, { question: "When is endodontic surgery needed?", answer: "Endodontic surgery may be recommended if:", bullets: ["Infection remains after root canal treatment", "A root fracture is suspected", "There are hidden canals or complex root structures", "A cyst or abscess has formed", "Persistent pain continues despite prior treatment"] }, { question: "What is the endodontic surgery procedure?", answer: "", bullets: ["Evaluation & Imaging — We assess the affected tooth using digital X-rays to locate the infection.", "Local Anesthesia — The area is numbed to ensure comfort.", "Small Incision in the Gum — The infected tissue around the root tip is accessed.", "Removal of Infection & Root Tip — The affected portion of the root is carefully removed.", "Sealing & Suturing — The root end is sealed, and the gum tissue is sutured to allow healing."] }, { question: "Is endodontic surgery painful?", answer: "Modern techniques and anesthesia make endodontic surgery comfortable for most patients. Mild swelling or discomfort may occur afterward but can usually be managed with medication and proper aftercare. Our team provides detailed post-operative instructions to support healing." }, { question: "What are the benefits of endodontic surgery?", answer: "", bullets: ["Eliminates persistent infection", "Preserves your natural tooth", "Prevents the need for extraction", "Protects surrounding teeth and bone", "Restores oral comfort"] }, { question: "What should you expect during recovery?", answer: "Healing typically takes a few days to a week. During recovery:", bullets: ["Avoid chewing on the treated side temporarily", "Maintain good oral hygiene", "Follow medication instructions", "Attend follow-up appointments as recommended"] }] },
  "wisdom-teeth-extractions": { intro: "Wisdom teeth often cause problems due to lack of space, impaction, or improper positioning. Timely removal prevents pain, crowding, and infection.", benefits: ["Prevents crowding of adjacent teeth", "Eliminates pain and pressure", "Reduces infection risk", "Performed under local or general anesthesia", "Quick recovery time"], process: "After taking X-rays to assess the position of the wisdom teeth, we administer anesthesia and remove the teeth. Post-operative instructions are provided for a smooth recovery.", faqs: [{ question: "Why do wisdom teeth need to be removed?", answer: "Wisdom teeth often cause issues because:", bullets: ["There is not enough room in the jaw", "They grow in at an angle (impacted teeth)", "They become partially erupted and trap bacteria", "They are difficult to clean", "They increase the risk of decay and gum infection"] }, { question: "What are the signs you may need wisdom teeth surgery?", answer: "You may require evaluation if you experience:", bullets: ["Jaw pain or pressure", "Swelling in the back of the mouth", "Red or swollen gums", "Difficulty opening your mouth", "Bad breath or unpleasant taste", "Recurring infection around the wisdom teeth"] }, { question: "What is an impacted wisdom tooth?", answer: "An impacted tooth is one that cannot fully erupt due to lack of space or obstruction by neighbouring teeth. Impacted wisdom teeth may:", bullets: ["Grow sideways", "Remain trapped under the gums", "Partially erupt and cause infection"] }, { question: "What is the wisdom teeth surgery procedure?", answer: "At Astra Dental Centre, your procedure typically includes:", bullets: ["Examination & Digital X-Rays — We assess the position of the wisdom teeth and create a treatment plan.", "Anesthesia — Local anesthesia ensures the area is fully numb for your comfort.", "Removal of the Tooth — The tooth is carefully removed. In some cases, a small incision is made to access impacted teeth.", "Sutures & Recovery Instructions — Stitches may be placed, and we provide detailed aftercare guidance."] }, { question: "What should you expect during recovery?", answer: "Most patients recover within a few days. During healing:", bullets: ["Mild swelling and discomfort are normal", "Ice packs can reduce swelling", "Soft foods are recommended", "Avoid smoking and vigorous rinsing", "Follow all post-operative instructions"] }, { question: "When is the best time to remove wisdom teeth?", answer: "Wisdom teeth are often easier to remove in the late teens or early twenties before roots fully develop. However, removal can be performed safely at any age if necessary. Early evaluation helps determine the ideal timing." }] },
  "bone-grafting": { intro: "Bone grafting rebuilds and strengthens the jawbone to support dental implants or treat bone loss caused by gum disease, injury, or tooth loss.", benefits: ["Creates adequate bone for implants", "Prevents further bone loss", "Restores facial structure", "Improves long-term oral health", "Multiple graft material options"], process: "Bone graft material is placed in the deficient area. Over time, your body integrates the graft and builds new bone. Healing is monitored over several months before implant placement.", faqs: [{ question: "Why is bone grafting needed?", answer: "Bone loss can occur due to:", bullets: ["Tooth extraction", "Periodontal (gum) disease", "Infection", "Trauma or injury", "Long-term missing teeth", "Natural bone resorption over time"] }, { question: "What is bone grafting?", answer: "Bone grafting involves placing bone material into areas where the jawbone has weakened or deteriorated. The graft material stimulates natural bone growth and integrates with your existing bone over time. Bone graft material may include:", bullets: ["Synthetic bone material", "Donor bone", "Your own natural bone (in certain cases)"] }, { question: "What types of bone grafting procedures are available?", answer: "", bullets: ["Socket Preservation — Performed immediately after tooth extraction to prevent bone loss.", "Ridge Augmentation — Restores bone width or height where significant bone loss has occurred.", "Sinus Lift (Sinus Augmentation) — Increases bone in the upper jaw near the molars when bone height is insufficient for implants."] }, { question: "What is the bone grafting procedure?", answer: "", bullets: ["Evaluation & Imaging — Digital X-rays help determine bone loss and treatment planning.", "Anesthesia — Local anesthesia ensures comfort during the procedure.", "Placement of Graft Material — The graft is carefully placed in the deficient area.", "Healing Period — The bone integrates naturally over several months."] }, { question: "What are the benefits of bone grafting?", answer: "", bullets: ["Restores lost jawbone", "Improves implant success rates", "Preserves facial structure", "Prevents further bone deterioration", "Supports long-term oral health"] }, { question: "Is bone grafting painful?", answer: "The procedure is typically well tolerated with local anesthesia. Mild swelling or discomfort may occur afterward, but this is manageable with prescribed or over-the-counter medication. We provide detailed aftercare instructions to support proper healing." }] },
  "dental-implants": { intro: "Dental implants are titanium posts surgically placed in the jawbone to serve as artificial tooth roots. They provide the most stable, natural-feeling foundation for crowns, bridges, or dentures.", benefits: ["Permanent tooth replacement solution", "Looks and functions like a natural tooth", "Preserves jawbone", "No impact on adjacent teeth", "High long-term success rate"], process: "The titanium implant is placed in the jawbone under local anesthesia. After 3–6 months of healing (osseointegration), an abutment and custom crown are attached.", faqs: [{ question: "What is a dental implant?", answer: "A dental implant is a small titanium post that is surgically placed into the jawbone to replace the root of a missing tooth. Once the implant integrates with the bone, it serves as a stable foundation for:", bullets: ["A dental crown (single tooth replacement)", "A dental bridge", "Implant-supported dentures"] }, { question: "Why choose dental implants?", answer: "Dental implants offer several important benefits:", bullets: ["Permanent and durable solution", "Prevents jawbone loss", "Does not rely on adjacent teeth for support", "Restores full chewing function", "Natural appearance"] }, { question: "Who is a candidate for dental implants?", answer: "You may be a good candidate if you:", bullets: ["Have one or more missing teeth", "Have healthy gums", "Have sufficient jawbone volume", "Are in good overall health"] }, { question: "What is the dental implant process?", answer: "", bullets: ["Consultation & Imaging — We evaluate your oral health and use digital imaging to assess bone structure.", "Implant Placement — The titanium implant is surgically placed into the jawbone under local anesthesia.", "Healing & Osseointegration — Over several months, the implant fuses with the bone, creating a strong foundation.", "Crown Placement — A custom-made crown is attached to complete your restoration."] }, { question: "How long do dental implants last?", answer: "With proper care and regular dental check-ups, dental implants can last many years — often decades. Maintaining good oral hygiene is essential to long-term success." }, { question: "Are dental implants safe?", answer: "Yes. Dental implants have a high success rate when placed by experienced professionals. We use modern techniques and precise planning to ensure optimal outcomes. Your comfort and safety are always our priority." }] },
  "impacted-canines": { intro: "When canine teeth fail to erupt properly, surgical exposure combined with orthodontic guidance can bring them into their correct position, preserving these critical teeth.", benefits: ["Preserves important canine teeth", "Avoids implant or bridge replacement", "Restores proper bite function", "Improves smile aesthetics", "Coordinated orthodontic and surgical care"], process: "Orthodontic brackets are placed on surrounding teeth. During a short surgical procedure, the gum is lifted to expose the impacted canine and a bracket is attached. A chain gradually guides it into position.", faqs: [{ question: "What are impacted canines?", answer: "Canine teeth — often called \"eye teeth\" — play an essential role in your bite, smile alignment, and overall dental function. When a canine fails to erupt properly and becomes trapped beneath the gums or jawbone, it is known as an impacted canine." }, { question: "What happens when a canine is impacted?", answer: "An impacted canine may:", bullets: ["Remain trapped in the jawbone", "Grow sideways", "Erupt in an incorrect position", "Be blocked by overcrowded teeth"] }, { question: "Why do canines become impacted?", answer: "Impacted canines may result from:", bullets: ["Overcrowding", "Extra teeth blocking eruption", "Delayed tooth development", "Genetic factors", "Early loss of baby teeth"] }, { question: "What are the signs of impacted canines?", answer: "In many cases, impacted canines cause no pain initially. However, signs may include:", bullets: ["Missing adult canine tooth after expected eruption age", "Swelling or tenderness in the gum area", "Shifting of neighbouring teeth", "Unexplained spacing changes"] }, { question: "What are the treatment options for impacted canines?", answer: "Treatment depends on the position of the tooth and the patient's age:", bullets: ["Orthodontic Guidance — In younger patients, early intervention may help guide eruption naturally.", "Surgical Exposure & Orthodontic Traction — A minor surgical procedure may be performed to expose the impacted tooth, followed by orthodontic treatment to guide it into proper position.", "Extraction — In rare cases where the tooth cannot be properly aligned, removal may be necessary."] }, { question: "Why is early treatment important?", answer: "Untreated impacted canines can lead to:", bullets: ["Damage to neighbouring teeth", "Cyst formation", "Infection", "Bite misalignment", "Cosmetic concerns"] }] },
  "gum-surgery": { intro: "When periodontal disease advances beyond what routine care can manage, gum surgery may be necessary to stop infection, restore gum health, and protect your teeth long term.", benefits: ["Treats advanced gum disease", "Reduces periodontal pockets", "Stops gum recession", "Protects tooth roots", "Preserves jawbone and teeth"], process: "We begin with a detailed examination and digital imaging to assess the extent of gum disease. Local anesthesia is used during treatment to ensure comfort. Post-operative instructions are provided for a smooth recovery.", faqs: [{ question: "When is gum surgery needed?", answer: "Gum surgery is typically recommended when periodontal (gum) disease has advanced beyond what routine cleanings or non-surgical treatments can manage. You may need gum surgery if you have:", bullets: ["Deep periodontal pockets around teeth", "Receding gums exposing tooth roots", "Persistent gum infection", "Loose teeth caused by bone loss", "Inflammation that does not improve with standard treatment"] }, { question: "What types of gum surgery are available?", answer: "Periodontal Pocket Reduction — When gum disease creates deep spaces between the teeth and gums, bacteria can collect and cause ongoing infection. Pocket reduction surgery gently lifts the gum tissue, removes bacteria and infected tissue, and repositions the gums to reduce pocket depth.\n\nGum Grafting — Gum recession can expose sensitive tooth roots and affect the appearance of your smile. A gum graft restores lost tissue by covering exposed areas and strengthening the gum line. Grafting helps:", bullets: ["Reduce sensitivity", "Protect tooth roots from decay", "Improve the appearance of receding gums", "Prevent further tissue loss"] }, { question: "What should you expect during gum surgery?", answer: "Your treatment begins with a detailed examination, including digital imaging when necessary. Local anesthesia is used to ensure comfort during surgery. We take the time to answer your questions so you feel informed and confident before proceeding." }, { question: "What should you expect after gum surgery?", answer: "Mild swelling or tenderness is normal after gum surgery and typically improves within a few days. We'll provide detailed aftercare instructions, including guidance on:", bullets: ["Managing discomfort", "Eating soft foods during healing", "Maintaining oral hygiene", "Follow-up visits"] }, { question: "Why is gum surgery important?", answer: "Untreated gum disease can lead to tooth loss and impact your overall health. Addressing the problem early and following through with recommended treatment helps protect both your smile and your well-being." }] },
  "prosthodontics": { intro: "Prosthodontics is the area of dentistry focused on restoring and replacing teeth using custom-made dental prosthetics. Our goal is to restore your smile so it functions properly and looks naturally balanced.", benefits: ["Restores damaged or missing teeth", "Improves chewing and speech", "Preserves jawbone structure", "Custom-made for a natural fit", "Supports long-term oral health"], process: "We begin with a thorough examination and digital imaging. Treatment options are clearly explained, including materials, timelines, and expected outcomes. Restorations are custom-designed to blend naturally with your smile.", faqs: [{ question: "What is prosthodontics?", answer: "Prosthodontics is the area of dentistry that focuses on restoring and replacing teeth. It includes treatments that repair damaged teeth and replace missing ones using custom-made dental prosthetics. The goal is simple: restore your smile so it functions properly and looks balanced." }, { question: "What treatments are included in prosthodontics?", answer: "Dental Crowns — A dental crown covers and protects a tooth that is weakened, cracked, or heavily filled. Each crown is custom-made to match the colour and contour of your natural teeth.\n\nDental Bridges — A bridge replaces one or more missing teeth by anchoring an artificial tooth to the natural teeth beside it. Bridges help:", bullets: ["Restore chewing ability", "Prevent shifting of nearby teeth", "Maintain facial structure", "Improve appearance"] }, { question: "What about dentures and implant options?", answer: "Dentures — Removable appliances designed to replace multiple missing teeth. We offer partial dentures for patients missing several teeth and full dentures for patients missing all teeth in the upper or lower arch.\n\nImplant-Supported Restorations — Dental implants can support crowns, bridges, or dentures for added stability. This option can significantly improve comfort and confidence compared to traditional removable appliances." }, { question: "Who can benefit from prosthodontic care?", answer: "You may benefit from prosthodontic treatment if you:", bullets: ["Have one or more missing teeth", "Have severely worn or damaged teeth", "Experience difficulty chewing", "Want to improve the appearance of your smile", "Need long-term restoration after trauma or decay"] }, { question: "What is involved in prosthodontic treatment?", answer: "Your consultation includes a thorough examination and digital imaging when necessary. We'll explain your options clearly, including timelines, materials, and expected outcomes. Our focus is on creating restorations that blend naturally with your smile and support long-term durability." }, { question: "Why is prosthodontic treatment important?", answer: "Replacing missing teeth is about more than cosmetics. Properly restored teeth:", bullets: ["Improve chewing efficiency", "Support clear speech", "Maintain jawbone structure", "Protect surrounding teeth from shifting", "Enhance facial balance"] }] },
  "childrens-dentistry": { intro: "We provide gentle, comprehensive dental care for children in a calm and welcoming environment. Our goal is to support healthy development from the very first tooth while building positive experiences that last a lifetime.", benefits: ["Early monitoring of dental development", "Cavity prevention with fluoride and sealants", "Gentle, child-friendly approach", "Education for parents and children", "Builds lifelong oral health habits"], process: "Each visit begins with a gentle examination and professional cleaning. We monitor growth, apply preventive treatments as needed, and take time to make children feel comfortable and confident in the dental chair.", faqs: [{ question: "Why is children's dental care important?", answer: "Children's teeth play an important role in:", bullets: ["Proper chewing and nutrition", "Speech development", "Guiding permanent teeth into position", "Overall health and confidence"] }, { question: "When should children start visiting the dentist?", answer: "Children should have their first dental visit by their first birthday or within six months of their first tooth erupting. Early visits are typically short and gentle. They allow your child to become familiar with the dental environment while we check that teeth and gums are developing properly." }, { question: "What services are included in children's dentistry?", answer: "Routine Exams and Cleanings — Regular checkups help keep your child's teeth clean and healthy. During each visit, we:", bullets: ["Examine teeth and gums", "Monitor growth and development", "Provide professional cleaning", "Offer fluoride treatment if needed"] }, { question: "What cavity prevention options are available?", answer: "Prevention is the foundation of children's dentistry. Fluoride treatments strengthen enamel and help prevent cavities. Dental sealants are protective coatings applied to the chewing surfaces of back teeth — they help block food and bacteria from settling into deep grooves where brushing may miss.\n\nIf your child develops a cavity, we use natural-looking tooth-coloured fillings to restore the tooth. We focus on gentle techniques to help children feel comfortable throughout treatment." }, { question: "How do you create a positive dental experience for children?", answer: "We understand that children can feel nervous about visiting the dentist. Our team takes a calm, friendly approach and moves at a pace that suits your child. We encourage questions and help children feel involved in their own dental care. A positive experience early on builds trust and reduces anxiety in the future." }, { question: "How can parents support their child's oral health at home?", answer: "You can support your child's oral health at home by:", bullets: ["Brushing twice daily with a fluoride toothpaste", "Supervising brushing until they can do it effectively on their own", "Limiting sugary snacks and drinks", "Encouraging regular flossing once teeth begin to touch"] }] },
  "periodontics": { intro: "Periodontics focuses on diagnosing and treating conditions that affect the gums and underlying bone. Early detection and consistent care are essential to protecting your teeth and overall health.", benefits: ["Treats and manages gum disease", "Prevents tooth and bone loss", "Non-surgical and surgical options", "Ongoing maintenance programs", "Supports overall systemic health"], process: "We begin with a thorough periodontal evaluation, measuring pocket depths and reviewing digital X-rays. Treatment is tailored to the severity of your condition, from deep cleaning to advanced surgical care.", faqs: [{ question: "What is periodontics?", answer: "Periodontics is the area of dentistry that treats conditions affecting the gums and underlying bone. Gum disease, also known as periodontal disease, begins with inflammation caused by plaque buildup. In its early stage (gingivitis), it may cause redness, swelling, or bleeding. If left untreated, it can progress to periodontitis, leading to bone loss and, eventually, tooth loss. Early diagnosis and treatment are key to preventing serious complications." }, { question: "What are the signs of gum disease?", answer: "You may need periodontal care if you notice:", bullets: ["Bleeding when brushing or flossing", "Swollen, tender, or red gums", "Persistent bad breath", "Receding gums", "Loose teeth", "Changes in your bite"] }, { question: "What periodontal services are available?", answer: "Periodontal Evaluation — We begin with a thorough assessment of your gum health. This includes measuring pocket depths and taking digital X-rays to evaluate bone levels.\n\nScaling and Root Planing — Often referred to as deep cleaning, this removes plaque and tartar from below the gum line. The root surfaces are smoothed to help the gums reattach and heal. This non-surgical treatment is typically effective for mild to moderate periodontal disease.\n\nPeriodontal Maintenance — After active treatment, ongoing maintenance visits are scheduled more frequently than routine cleanings to monitor gum health and prevent recurrence.\n\nAdvanced Periodontal Treatment — For more advanced cases, surgical procedures may be recommended to reduce deep pockets, remove infection, or regenerate lost tissue and bone." }, { question: "Why is periodontal health important?", answer: "Gum disease doesn't just affect your mouth. Research suggests a connection between periodontal health and overall health conditions, including heart disease and diabetes. Treating gum disease helps:", bullets: ["Preserve natural teeth", "Protect jawbone structure", "Reduce inflammation", "Improve long-term oral stability"] }, { question: "What is the approach to periodontal care?", answer: "At Astra Dental Centre, we emphasize early detection and prevention. Regular checkups, professional cleanings, and strong home care habits are your best defense against periodontal disease. If you are at higher risk due to smoking, medical conditions, or family history, we'll develop a customized care plan to monitor and protect your gum health." }] },
};

export default function ServiceDetailPage() {
  const { categorySlug, serviceSlug } = useParams<{ categorySlug: string; serviceSlug: string }>();
  const contentRef = useScrollAnimation<HTMLDivElement>();
  const whyRef = useScrollAnimation<HTMLDivElement>();

  const [dbBeforeAfters, setDbBeforeAfters] = useState<ServiceBeforeAfter[]>([]);
  const [dbServiceImage, setDbServiceImage] = useState<ServiceImage | null>(null);
  const [imagesReady, setImagesReady] = useState(false);

  useEffect(() => {
    if (!serviceSlug) return;
    setImagesReady(false);
    setDbBeforeAfters([]);
    setDbServiceImage(null);
    Promise.all([
      getServiceBeforeAfters(serviceSlug),
      getServiceImage(serviceSlug),
    ]).then(([bas, img]) => {
      setDbBeforeAfters(bas);
      setDbServiceImage(img);
      setImagesReady(true);
    });
  }, [serviceSlug]);

  if (!categorySlug || !serviceSlug) return <Navigate to="/langley-dental-services/" replace />;

  const service = getServiceBySlug(categorySlug, serviceSlug);
  const category = getCategoryBySlug(categorySlug);

  if (!service || !category) return <Navigate to="/langley-dental-services/" replace />;

  const details = serviceDetails[serviceSlug];
  const extra = serviceDetailExtras[serviceSlug];
  const seoTitle = extra?.seoTitle ?? `${service.title} in Langley, BC`;

  const heroImageUrl = imagesReady
    ? (dbServiceImage?.hero_image_url || null)
    : null;

  const beforeAfterItems: Array<{ label: string; before: string; after: string }> = imagesReady
    ? dbBeforeAfters.length > 0
      ? dbBeforeAfters.map((b) => ({ label: b.label, before: b.before_image_url, after: b.after_image_url }))
      : (extra?.beforeAfter || [])
    : [];

  return (
    <>
      <Hero
        title={seoTitle}
        subtitle={service.description}
        compact
        breadcrumb={[
          { label: "Langley Dental Services", href: "/langley-dental-services/" },
          { label: category.title, href: category.categoryPath },
          { label: service.title, href: `/${categorySlug}/${serviceSlug}/` },
        ]}
      />

      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">

            {/* Main */}
            <div ref={contentRef} className="fade-up lg:col-span-2">
              {details ? (
                <>
                  {/* Intro */}
                  <div className="mb-8">
                    <span className="section-label mb-3">About This Treatment</span>
                    <h2 className="font-poppins text-2xl font-bold text-navy-900 mb-4 leading-tight">
                      {seoTitle} at Astra Dental Centre
                    </h2>
                    <p className="text-gray-700 leading-relaxed">{details.intro}</p>
                  </div>

                  {/* Benefits + Process */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
                    <div className="bg-surface rounded-2xl p-6">
                      <h2 className="font-poppins text-base font-bold text-navy-900 mb-4">Key Benefits</h2>
                      <ul className="space-y-2.5">
                        {details.benefits.map((benefit) => (
                          <li key={benefit} className="flex items-start gap-2.5">
                            <CheckCircle size={14} className="text-teal-500 flex-shrink-0 mt-0.5" />
                            <span className="text-sm text-gray-700">{benefit}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                    <div className="bg-surface rounded-2xl p-6">
                      <h2 className="font-poppins text-base font-bold text-navy-900 mb-4">What to Expect</h2>
                      <p className="text-sm text-gray-600 leading-relaxed">{details.process}</p>
                    </div>
                  </div>

                  {/* Before / After */}
                  {beforeAfterItems.length > 0 && (
                    <div className="mb-10">
                      <h2 className="font-poppins text-lg font-bold text-navy-900 mb-5">Before &amp; After</h2>
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                        {beforeAfterItems.map((item) => (
                          <Compare
                            key={item.label}
                            firstImage={item.after}
                            secondImage={item.before}
                            firstImageClassName="object-cover"
                            secondImageClassname="object-cover"
                            className="h-52 w-full"
                            slideMode="hover"
                            label={item.label}
                          />
                        ))}
                      </div>
                      <p className="text-[11px] text-gray-400 mt-3 italic">
                        Images are for illustrative purposes only and do not represent actual patient results.
                      </p>
                    </div>
                  )}

                  {/* Who is this for */}
                  {extra?.whoFor && extra.whoFor.length > 0 && (
                    <div className="mb-10">
                      <h2 className="font-poppins text-lg font-bold text-navy-900 mb-5">
                        Who Is {service.title} For?
                      </h2>
                      <ul className="space-y-3">
                        {extra.whoFor.map((item) => (
                          <li key={item.label} className="flex items-start gap-3">
                            <CheckCircle size={14} className="text-teal-500 mt-0.5 flex-shrink-0" />
                            <span className="text-sm text-gray-700">
                              <span className="font-semibold text-navy-900">{item.label}</span> — {item.desc}
                            </span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </>
              ) : (
                <div className="bg-teal-50 border border-teal-100 rounded-2xl p-6 mb-8">
                  <p className="text-sm text-teal-700 font-medium">
                    Detailed information about {service.title} is coming soon. Please contact us for more information.
                  </p>
                </div>
              )}

              {/* Other services in category */}
              {category.services.length > 1 && (
                <>
                  <h2 className="font-poppins text-lg font-bold text-navy-900 mb-4">
                    Other {category.title} Services
                  </h2>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {category.services
                      .filter((s) => s.slug !== serviceSlug)
                      .map((s) => (
                        <ServiceCard
                          key={s.slug}
                          title={s.title}
                          description={s.description}
                          href={`/${categorySlug}/${s.slug}/`}
                          variant="compact"
                        />
                      ))}
                  </div>
                </>
              )}
            </div>

            {/* Sidebar */}
            <aside className="space-y-5">
              {heroImageUrl && (
                <div className="rounded-2xl overflow-hidden shadow-card">
                  <img
                    src={heroImageUrl}
                    alt={dbServiceImage?.hero_image_alt || `${service.title} in Langley BC`}
                    className="w-full h-48 object-cover"
                  />
                </div>
              )}

              <div className="bg-navy-950 rounded-2xl p-6 text-white">
                <h3 className="font-poppins font-semibold text-base mb-2">Book a Consultation</h3>
                <p className="text-navy-200 text-sm leading-relaxed mb-4">
                  Interested in {service.title} in Langley? Our team is here to help.
                </p>
                <Link to="/contact-us/" className="btn-teal w-full !text-xs !py-3">
                  Book Now <ArrowRight size={13} />
                </Link>
                <a href={`tel:${BUSINESS.phone}`} className="mt-2 flex items-center justify-center gap-2 border border-white/20 text-white text-xs font-medium py-2.5 rounded-full hover:bg-white/10 transition-colors">
                  <Phone size={12} />
                  {BUSINESS.phone}
                </a>
              </div>

              <div className="bg-surface rounded-2xl p-5">
                <h3 className="font-poppins font-semibold text-xs text-navy-900 uppercase tracking-widest mb-3">
                  More {category.title}
                </h3>
                <Link
                  to={category.categoryPath}
                  className="flex items-center gap-1 text-sm text-teal-600 hover:text-teal-800 font-semibold mb-3 transition-colors"
                >
                  <ArrowLeft size={11} /> All {category.title}
                </Link>
                <div className="space-y-1">
                  {category.services
                    .filter((s) => s.slug !== serviceSlug)
                    .map((s) => (
                      <Link
                        key={s.slug}
                        to={`/${categorySlug}/${s.slug}/`}
                        className="flex items-center justify-between text-sm text-gray-600 hover:text-navy-900 hover:bg-white py-2 px-3 rounded-lg transition-colors"
                      >
                        {s.title}
                        <ArrowRight size={11} className="text-gray-300" />
                      </Link>
                    ))}
                </div>
              </div>

              <div className="bg-surface rounded-2xl p-5">
                <h3 className="font-poppins font-semibold text-xs text-navy-900 uppercase tracking-widest mb-3">All Services</h3>
                <div className="space-y-1">
                  {serviceCategories
                    .filter((c) => c.slug !== categorySlug)
                    .map((cat) => (
                      <Link
                        key={cat.slug}
                        to={cat.categoryPath}
                        className="flex items-center justify-between text-sm text-gray-600 hover:text-navy-900 hover:bg-white py-2 px-3 rounded-lg transition-colors"
                      >
                        {cat.title}
                        <ArrowRight size={11} className="text-gray-300" />
                      </Link>
                    ))}
                </div>
              </div>
            </aside>
          </div>
        </div>
      </section>

      {/* Why Choose Us */}
      <section className="py-14 bg-surface">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-xl mb-8">
            <span className="section-label mb-3">Why Astra Dental</span>
            <h2 className="font-poppins text-2xl font-bold text-navy-900 mb-2 leading-tight">
              Why Choose Astra Dental Centre in Langley?
            </h2>
          </div>
          <div ref={whyRef} className="fade-up grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4">
            {whyChooseUs.map((item) => (
              <HolographicCard key={item.title} className="bg-white p-4 text-center">
                <p className="font-poppins font-semibold text-navy-900 text-xs mb-1 leading-tight">{item.title}</p>
                <p className="text-gray-500 text-[11px] leading-relaxed">{item.desc}</p>
              </HolographicCard>
            ))}
          </div>
        </div>
      </section>

      {details && details.faqs.length > 0 && (
        <FAQSection faqs={details.faqs} title={`${service.title} FAQ`} />
      )}

      <div className="py-5 bg-white border-t border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center gap-4">
          <Link
            to={category.categoryPath}
            className="inline-flex items-center gap-2 text-sm text-teal-600 hover:text-teal-800 font-medium transition-colors"
          >
            <ArrowLeft size={13} />
            Back to {category.title}
          </Link>
          <span className="text-gray-200">|</span>
          <Link
            to="/langley-dental-services/"
            className="inline-flex items-center gap-2 text-sm text-teal-600 hover:text-teal-800 font-medium transition-colors"
          >
            All Services
          </Link>
        </div>
      </div>

      <CTASection />
    </>
  );
}
